'use strict';

/**
* Evaluate the natural logarithm of the Erlang distribution cumulative distribution function (CDF).
*
* @module @stdlib/stats/base/dists/erlang/logcdf
*
* @example
* var logcdf = require( '@stdlib/stats/base/dists/erlang/logcdf' );
*
* var y = logcdf( 2.0, 8, 3.0 );
* // returns ~-1.362
*
* y = logcdf( 0.0, 1, 1.0 );
* // returns -Infinity
*
* var mylogcdf = logcdf.factory( 2, 0.5 );
* y = mylogcdf( 6.0 );
* // returns ~-0.222
*
* y = mylogcdf( 2.0 );
* // returns ~-1.331
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var factory = require( './factory.js' );


// MAIN //

setReadOnly( main, 'factory', factory );


// EXPORTS //

module.exports = main;
